/* User-supplied discovery performance. Audio and captions share the media clock. */
(()=>{
 const normalize=text=>text.toLowerCase().replace(/[^a-z]/g,''),key=normalize('I think I know him too myself');
 const words=[{text:'I',start:.48,end:.68},{text:'think',start:.68,end:.9},{text:'I',start:.9,end:1.06},{text:'know',start:1.06,end:1.3},{text:'him',start:1.3,end:2},{text:'too',start:2.08,end:2.86},{text:'myself',start:3.16,end:3.6}];
 window.sampleDiscoveryVoice=time=>({word:words.find(w=>time>=w.start&&time<w.end)?.text||'',caption:time>=.48&&time<3.02?'I think I know him too…':time>=3.16&&time<4.04?'Myself!':''});
 const recording=new Audio('data:audio/mp4;base64,');recording.preload='auto';let active=null,stalled=false;
 window.isRecordedCinematicLine=line=>line?.who==='RED DAWN'&&normalize(line.text)===key;
 window.updateRecordedCinematicDialogue=()=>{if(!active)return;const time=recording.currentTime,part=window.sampleDiscoveryVoice(time),playing=!recording.paused&&!recording.ended&&!stalled,word=words.find(w=>time>=w.start&&time<w.end),now=performance.now();window.heroDialogueSpeech={who:active.who,text:active.text,word:part.word,speaking:playing&&!!word,hasBoundary:true,wordDuration:word?word.end-word.start:0,started:now-(word?(time-word.start)*1000:0),began:now-time*1000};};
 window.recordedCinematicCaption=line=>window.isRecordedCinematicLine(line)?(active?window.sampleDiscoveryVoice(recording.currentTime).caption:''):null;
 window.playRecordedCinematicLine=(line,fallback)=>{if(!window.isRecordedCinematicLine(line))return false;active=line;stalled=false;recording.currentTime=0;recording.play().then(()=>window.updateRecordedCinematicDialogue()).catch(error=>{active=null;console.warn('Recorded dialogue playback:',error);fallback?.();});return true;};
 recording.addEventListener('waiting',()=>{stalled=true;window.updateRecordedCinematicDialogue();});recording.addEventListener('playing',()=>{stalled=false;window.updateRecordedCinematicDialogue();});for(const event of ['pause','ended'])recording.addEventListener(event,()=>{if(window.heroDialogueSpeech?.who===active?.who)window.heroDialogueSpeech.speaking=false;});
 let resumeAfterPause=false;function pauseWithScene(paused){if(paused){resumeAfterPause=!!active&&!recording.paused;recording.pause();}else if(resumeAfterPause&&active){resumeAfterPause=false;recording.play().catch(()=>{});}}document.addEventListener('visibilitychange',()=>pauseWithScene(document.hidden));window.addEventListener('hero-graphics-pause',event=>pauseWithScene(event.detail.paused));
 window.stopRecordedCinematicDialogue=()=>{recording.pause();recording.currentTime=0;active=null;};
})();
